  const [currentSeats, setCurrentSeats] = useState(user?.currentSeats || 0);
  const [isSaving, setIsSaving] = useState(false);

  const handleSave = async () => {
    setIsSaving(true);
    const result = await updateProfile({
      serviceTypes: selectedServices,
      currentSeats
    });
