          </Card>
        )}

        <Button 
          onClick={handleSave}
          disabled={isSaving}
          className="w-full bg-[#E11D48] hover:bg-[#BE123C] uppercase mt-4"
        >
          {isSaving ? 'Saving...' : 'Save Service Types'}
        </Button>
      </div>
    </div>
  );
}
